for a,b,c in [(2,3,5),(4,2,6),(3,5,4),(6,2,3),(4,4,3)]:
 term('계산',f'세 속성 A, B, C의 도메인 원소 수가 각각 {a}, {b}, {c}개다. 추가 제약이 없다면 가능한 튜플의 최대 수는?',str(a*b*c),f'각 속성의 가능한 값을 곱합니다. {a} × {b} × {c} = {a*b*c}.',1,sid=3)
for bits in [24,25,26,27,28,29,30]:
 hosts=2**(32-bits)-2
 term('계산',f'일반적인 IPv4 서브넷 /{bits}에서 네트워크 주소와 브로드캐스트 주소를 제외한 사용 가능한 호스트 주소 수는?',str(hosts),f'호스트 비트는 32 − {bits} = {32-bits}비트입니다. 2^{32-bits} − 2 = {hosts}개입니다.',11,sid=3)
for rows,cols in [(7,4),(12,5),(3,8),(9,6),(15,3)]:
 term('계산',f'{rows}개 행과 {cols}개 열을 가진 릴레이션의 카디널리티와 차수를 순서대로 쓰세요. (쉼표로 구분)',f'{rows}, {cols}',f'카디널리티는 튜플 수 {rows}, 차수는 속성 수 {cols}입니다.',1,sid=3)
for nums in [[7,2,9,4,1],[8,5,3,6,2],[4,9,1,7,3],[6,3,8,2,5]]:
 arr=nums[:]
 for i in range(len(arr)-1):
  if arr[i]>arr[i+1]: arr[i],arr[i+1]=arr[i+1],arr[i]
 term('계산',f'배열 {", ".join(map(str,nums))}에 왼쪽부터 인접 원소를 비교하는 오름차순 버블 정렬을 1회전 수행한 결과는? (쉼표로 구분)',', '.join(map(str,arr)),f'인접한 두 값을 비교해 큰 값을 오른쪽으로 보냅니다. 1회전 후 최댓값 {max(nums)}이 맨 오른쪽에 놓입니다.',2,sid=3)
for a,m,b in [(6,9,12),(3,6,9),(2,5,8),(4,7,10)]:
 term('계산',f'PERT에서 낙관 시간 {a}일, 최빈 시간 {m}일, 비관 시간 {b}일이다. 기대 소요 시간은 몇 일인가?',str((a+4*m+b)//6),f'기대 시간 = (낙관 + 4 × 최빈 + 비관) ÷ 6 = ({a} + 4 × {m} + {b}) ÷ 6 = {(a+4*m+b)//6}일.',5)
